select m.name as brand,t.model_family,t.interval_months,count(s.id) as steps from public.bf_med_master_pm_templates t join public.bf_med_manufacturers m on m.id=t.manufacturer_id join public.bf_med_master_pm_steps s on s.template_id=t.id where t.reference like 'OEM-20261110-B3;%' group by m.name,t.model_family,t.interval_months order by m.name,t.model_family;
